(function() {
  // 防止重复注入
  if (window.__AICOIN_DOM_OBSERVER__) return;
  window.__AICOIN_DOM_OBSERVER__ = true;

  // 检查元素文本内容
  function checkElement(element) {
    if (!element || !element.textContent) return;
    const text = element.textContent.trim();

    // 检测登录次数过多
    if (text.includes('登录次数过多') ||
        text.includes('Too many login attempts')) {
      console.log('[AICOIN_DOM_EVENT]登录次数过多', JSON.stringify({
        text: text,
        tagName: element.tagName,
        className: element.className,
        id: element.id
      }));
    }

    // 检测子账户无法登录
    if (text.includes('子账户已无法登录') ||
        text.includes('子账号已无法登录') ||
        text.includes('Sub-account login is not supported')) {
      console.log('[AICOIN_DOM_EVENT]子账户已无法登录', JSON.stringify({
        text: text,
        tagName: element.tagName,
        className: element.className,
        id: element.id
      }));
    }
  }

  // 创建MutationObserver监听DOM变化
  const observer = new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
      // 检查新增的节点
      mutation.addedNodes.forEach((node) => {
        if (node.nodeType === Node.ELEMENT_NODE) {
          checkElement(node);
          // 检查子元素
          node.querySelectorAll && node.querySelectorAll('div, span, p').forEach(checkElement);
        }
      });

      // 检查文本变化
      if (mutation.type === 'characterData' || mutation.type === 'childList') {
        checkElement(mutation.target);
      }
    });
  });

  // 开始观察
  observer.observe(document.body, {
    childList: true,
    subtree: true,
    characterData: true,
    characterDataOldValue: true
  });

  // 立即检查已存在的元素
  document.querySelectorAll('div, span, p').forEach(checkElement);
})();
